-- Product resource aggregates and durable studio files. No owner rows or vendor models seeded.
CREATE SCHEMA resources;
CREATE TABLE resources.catalog_imports(version text PRIMARY KEY,source_hash text NOT NULL CHECK(length(source_hash)=64),source_name text NOT NULL,imported_at timestamptz NOT NULL DEFAULT now(),row_count integer NOT NULL);
CREATE TABLE resources.categories(namespace text NOT NULL,id text NOT NULL,parent_id text,name text NOT NULL,context jsonb NOT NULL DEFAULT '{}',content jsonb NOT NULL,sort_order integer NOT NULL DEFAULT 0,source_version text REFERENCES resources.catalog_imports(version),PRIMARY KEY(namespace,id));
CREATE TABLE resources.catalog_values(namespace text NOT NULL,key text NOT NULL,content jsonb NOT NULL,context jsonb NOT NULL DEFAULT '{}',source_version text REFERENCES resources.catalog_imports(version),PRIMARY KEY(namespace,key));
CREATE TABLE resources.items(id text PRIMARY KEY,family text NOT NULL CHECK(family IN('CHARACTER','PROMPT','SKILL','WORKFLOW','APP','VOICE','DIRECTOR_PROJECT','DIRECTOR_MODEL','DIRECTOR_DEFINE','HOME_HIGHLIGHT','INSPIRATION_TEMPLATE','ANIMATION','STUDIO_BLOCK')),owner_id text REFERENCES public.users(id),scope text NOT NULL CHECK(scope IN('SYSTEM','USER')),name text NOT NULL CHECK(char_length(btrim(name)) BETWEEN 1 AND 120),description text NOT NULL DEFAULT '',content jsonb NOT NULL CHECK(jsonb_typeof(content)='object'),category_ids text[] NOT NULL DEFAULT '{}',cover_asset_id text,cover_url text NOT NULL DEFAULT '',revision bigint NOT NULL DEFAULT 1 CHECK(revision>0),version text NOT NULL DEFAULT '1',source_version text REFERENCES resources.catalog_imports(version),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,UNIQUE(id,owner_id),CHECK((scope='USER' AND owner_id IS NOT NULL AND source_version IS NULL) OR (scope='SYSTEM' AND owner_id IS NULL)));
CREATE INDEX resource_items_page ON resources.items(family,owner_id,updated_at DESC,id) WHERE deleted_at IS NULL;
CREATE TABLE resources.asset_refs(resource_id text NOT NULL,owner_id text NOT NULL,asset_id text NOT NULL,PRIMARY KEY(resource_id,asset_id),FOREIGN KEY(resource_id,owner_id) REFERENCES resources.items(id,owner_id),FOREIGN KEY(asset_id,owner_id) REFERENCES public.assets(id,owner_id));
CREATE INDEX resource_refs_asset ON resources.asset_refs(asset_id,owner_id);
CREATE TABLE resources.favorites(owner_id text NOT NULL REFERENCES public.users(id),resource_id text NOT NULL REFERENCES resources.items(id),favorited boolean NOT NULL,revision bigint NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,resource_id));
CREATE TABLE resources.usage_records(id text PRIMARY KEY,owner_id text NOT NULL REFERENCES public.users(id),resource_id text NOT NULL REFERENCES resources.items(id),project_id text,node_id text,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,owner_id) REFERENCES public.projects(id,owner_id));
CREATE INDEX resource_usage_owner ON resources.usage_records(owner_id,resource_id,created_at DESC);
CREATE TABLE resources.preferences(owner_id text PRIMARY KEY REFERENCES public.users(id),revision bigint NOT NULL DEFAULT 1,shortcut_key_config jsonb NOT NULL DEFAULT '{}',buzzy_pop_flag boolean NOT NULL DEFAULT false,tag_revision bigint NOT NULL DEFAULT 1);
CREATE TABLE resources.tags(id text PRIMARY KEY,owner_id text NOT NULL REFERENCES resources.preferences(owner_id),name text NOT NULL,color text NOT NULL,visible boolean NOT NULL DEFAULT true,sort_order integer NOT NULL CHECK(sort_order>=0),UNIQUE(owner_id,name));
CREATE TABLE resources.studio_projects(id text PRIMARY KEY,owner_id text NOT NULL REFERENCES public.users(id),project_id text,title text NOT NULL,revision bigint NOT NULL DEFAULT 1 CHECK(revision>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,UNIQUE(id,owner_id),FOREIGN KEY(project_id,owner_id) REFERENCES public.projects(id,owner_id));
CREATE TABLE resources.studio_files(project_id text NOT NULL,owner_id text NOT NULL,path text NOT NULL,content bytea NOT NULL CHECK(octet_length(content)<=8388608),mime_type text NOT NULL,revision bigint NOT NULL CHECK(revision>0),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(project_id,path),FOREIGN KEY(project_id,owner_id) REFERENCES resources.studio_projects(id,owner_id));
CREATE TABLE resources.studio_sessions(project_id text NOT NULL,owner_id text NOT NULL,session_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(project_id,session_id),UNIQUE(session_id),FOREIGN KEY(project_id,owner_id) REFERENCES resources.studio_projects(id,owner_id),FOREIGN KEY(session_id,owner_id) REFERENCES assistant.conversations(id,owner_id));
-- Library aggregate extension; existing ROLE/SCENE identity trigger stays intact.
CREATE TABLE library.folders(id text PRIMARY KEY,owner_id text NOT NULL REFERENCES library.collections(owner_id),name text NOT NULL,category_code text NOT NULL,parent_id text,kind text NOT NULL DEFAULT 'MIXED' CHECK(kind='MIXED'),revision bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,UNIQUE(id,owner_id),FOREIGN KEY(parent_id,owner_id) REFERENCES library.folders(id,owner_id),CHECK(parent_id IS NULL OR parent_id<>id));
CREATE TABLE library.folder_media_refs(folder_id text NOT NULL,owner_id text NOT NULL,asset_id text NOT NULL,sort_order integer NOT NULL CHECK(sort_order BETWEEN 0 AND 99),PRIMARY KEY(folder_id,asset_id),UNIQUE(folder_id,sort_order),FOREIGN KEY(folder_id,owner_id) REFERENCES library.folders(id,owner_id),FOREIGN KEY(asset_id,owner_id) REFERENCES public.assets(id,owner_id));
ALTER TABLE library.items ADD COLUMN category_code text NOT NULL DEFAULT 'USER_OTHER',ADD COLUMN folder_id text;
ALTER TABLE library.items ADD CONSTRAINT library_item_folder_fk FOREIGN KEY(folder_id,owner_id) REFERENCES library.folders(id,owner_id);
CREATE TABLE library.nodes(id text PRIMARY KEY,owner_id text NOT NULL REFERENCES library.collections(owner_id),name text NOT NULL,kind text NOT NULL,category_code text NOT NULL,folder_id text,content jsonb NOT NULL,thumbnail_asset_id text,revision bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),deleted_at timestamptz,UNIQUE(id,owner_id),FOREIGN KEY(folder_id,owner_id) REFERENCES library.folders(id,owner_id),FOREIGN KEY(thumbnail_asset_id,owner_id) REFERENCES public.assets(id,owner_id));
CREATE TABLE library.node_asset_refs(node_id text NOT NULL,owner_id text NOT NULL,asset_id text NOT NULL,PRIMARY KEY(node_id,asset_id),FOREIGN KEY(node_id,owner_id) REFERENCES library.nodes(id,owner_id),FOREIGN KEY(asset_id,owner_id) REFERENCES public.assets(id,owner_id));
CREATE INDEX library_node_ref_asset ON library.node_asset_refs(asset_id,owner_id);
CREATE INDEX library_nodes_page ON library.nodes(owner_id,folder_id,updated_at DESC,id) WHERE deleted_at IS NULL;
CREATE INDEX library_folders_page ON library.folders(owner_id,parent_id,updated_at DESC,id) WHERE deleted_at IS NULL;
-- Root asset deletion uses this one active reference view in its existing owner transaction.
CREATE VIEW resources.active_asset_references AS
 SELECT r.asset_id,r.owner_id,'RESOURCE'::text AS source_type,r.resource_id AS source_id FROM resources.asset_refs r JOIN resources.items i ON i.id=r.resource_id AND i.owner_id=r.owner_id WHERE i.deleted_at IS NULL
 UNION ALL SELECT r.asset_id,r.owner_id,'LIBRARY_GALLERY',r.item_id FROM library.item_media_refs r JOIN library.items i ON i.id=r.item_id AND i.owner_id=r.owner_id WHERE i.deleted_at IS NULL
 UNION ALL SELECT r.asset_id,r.owner_id,'LIBRARY_NODE',r.node_id FROM library.node_asset_refs r JOIN library.nodes i ON i.id=r.node_id AND i.owner_id=r.owner_id WHERE i.deleted_at IS NULL
 UNION ALL SELECT r.asset_id,r.owner_id,'LIBRARY_FOLDER',r.folder_id FROM library.folder_media_refs r JOIN library.folders f ON f.id=r.folder_id AND f.owner_id=r.owner_id WHERE f.deleted_at IS NULL;
CREATE TABLE resources.catalog_media(id text PRIMARY KEY,path text NOT NULL CHECK(path LIKE '/project/assets/%' AND position('..' in path)=0),source_version text NOT NULL REFERENCES resources.catalog_imports(version));
-- Only roots reachable through entirely active owner parents are visible.
CREATE VIEW library.visible_folders AS WITH RECURSIVE visible(id,owner_id) AS (
 SELECT id,owner_id FROM library.folders WHERE parent_id IS NULL AND deleted_at IS NULL
 UNION ALL SELECT c.id,c.owner_id FROM library.folders c JOIN visible p ON p.id=c.parent_id AND p.owner_id=c.owner_id WHERE c.deleted_at IS NULL
) SELECT f.* FROM library.folders f JOIN visible v ON v.id=f.id AND v.owner_id=f.owner_id;
CREATE OR REPLACE VIEW resources.active_asset_references AS
 SELECT r.asset_id,r.owner_id,'RESOURCE'::text AS source_type,r.resource_id AS source_id FROM resources.asset_refs r JOIN resources.items i ON i.id=r.resource_id AND i.owner_id=r.owner_id WHERE i.deleted_at IS NULL
 UNION ALL SELECT r.asset_id,r.owner_id,'LIBRARY_GALLERY',r.item_id FROM library.item_media_refs r JOIN library.items i ON i.id=r.item_id AND i.owner_id=r.owner_id WHERE i.deleted_at IS NULL AND (i.folder_id IS NULL OR EXISTS(SELECT 1 FROM library.visible_folders f WHERE f.id=i.folder_id AND f.owner_id=i.owner_id))
 UNION ALL SELECT r.asset_id,r.owner_id,'LIBRARY_NODE',r.node_id FROM library.node_asset_refs r JOIN library.nodes i ON i.id=r.node_id AND i.owner_id=r.owner_id WHERE i.deleted_at IS NULL AND (i.folder_id IS NULL OR EXISTS(SELECT 1 FROM library.visible_folders f WHERE f.id=i.folder_id AND f.owner_id=i.owner_id))
 UNION ALL SELECT r.asset_id,r.owner_id,'LIBRARY_FOLDER',r.folder_id FROM library.folder_media_refs r JOIN library.visible_folders f ON f.id=r.folder_id AND f.owner_id=r.owner_id;
CREATE TABLE resources.studio_events(seq bigserial PRIMARY KEY,owner_id text NOT NULL REFERENCES public.users(id),project_id text NOT NULL,path text NOT NULL,event text NOT NULL CHECK(event='file-change'),revision bigint NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(project_id,owner_id) REFERENCES resources.studio_projects(id,owner_id));
CREATE INDEX studio_events_owner_cursor ON resources.studio_events(owner_id,seq);
CREATE FUNCTION resources.guard_identity() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF NEW.id IS DISTINCT FROM OLD.id OR NEW.owner_id IS DISTINCT FROM OLD.owner_id OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.revision<=OLD.revision OR (OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS DISTINCT FROM OLD.deleted_at) THEN RAISE EXCEPTION 'resource identity/revision/deletion violation' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER resource_identity BEFORE UPDATE ON resources.items FOR EACH ROW EXECUTE FUNCTION resources.guard_identity();
CREATE TRIGGER studio_identity BEFORE UPDATE ON resources.studio_projects FOR EACH ROW EXECUTE FUNCTION resources.guard_identity();
CREATE TRIGGER folder_identity BEFORE UPDATE ON library.folders FOR EACH ROW EXECUTE FUNCTION resources.guard_identity();
CREATE TRIGGER node_identity BEFORE UPDATE ON library.nodes FOR EACH ROW EXECUTE FUNCTION resources.guard_identity();
